const express = require('express');
const fs = require('fs');
const path = require('path');
const { pipeline, Transform } = require('stream');
const { TelemetryBatch } = require('../models/telemetryBatch');

const app = express();

class SensorBatchTransform extends Transform {
  constructor() {
    super({ objectMode: false });
  }

  _transform(chunk, encoding, callback) {
    const lines = chunk.toString('utf8').trim().split('\n');
    const formatted = lines
      .map((line) => {
        try {
          const obj = JSON.parse(line);
          obj.stream_exported_at = new Date().toISOString();
          return JSON.stringify(obj);
        } catch {
          return line;
        }
      })
      .join('\n');
    callback(null, Buffer.from(formatted + '\n'));
  }
}

app.get('/iot/telemetry/batches/:batchId/download', async (req, res) => {
  if (!req.user || !req.user.facilityId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Validate that the telemetry batch was produced by the caller's facility
  const batchRecord = await TelemetryBatch.findOne({
    where: {
      batchId: req.params.batchId,
      facilityId: req.user.facilityId
    }
  });

  if (!batchRecord) {
    return res.status(403).json({ error: 'Access denied or batch does not belong to facility' });
  }

  const batchFile = path.join('/var/iot/batches', `${req.params.batchId}.ndjson`);
  if (!fs.existsSync(batchFile)) {
    return res.status(404).json({ error: 'Batch archive not found' });
  }

  res.setHeader('Content-Type', 'application/x-ndjson');
  res.setHeader('Content-Disposition', `attachment; filename="batch_${req.params.batchId}.ndjson"`);

  const readStream = fs.createReadStream(batchFile);
  const transformer = new SensorBatchTransform();

  pipeline(readStream, transformer, res, (err) => {
    if (err && !res.headersSent) {
      res.status(500).json({ error: 'Telemetry stream error' });
    }
  });
});

app.listen(7788);
